{
  "title": "Reykjavik on a shoestring",
  "summary": "A gentler, wallet-friendly wander through Reykjavik's free sights, local flavour, and a proper meal without the splurge.",
  "stops": [
    {
      "poi_id": "p11",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "The crew's must-do stays put; those whale models are worth every minute, even if the entry fee makes my feathers twitch.",
      "poi_id": "p11"
    },
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": null,
      "note": "Free and full of local life, this market is the thrifty heart of the day.",
      "poi_id": "p12"
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "A short ride for open air and a lighthouse photo, no króna required.",
      "poi_id": "p13"
    },
    {
      "poi_id": "p17",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch at Kaffi Loki keeps the budget happy and the rye bread warm.",
      "poi_id": "p17"
    },
    {
      "poi_id": "p14",
      "kind": "activity",
      "must_do_id": null,
      "note": "A stroll down Laugavegur for window-shopping and people-watching; cheaper than the old plan.",
      "poi_id": "p14"
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner at Hlemmur Mathöll, where the options are plenty and the prices are kind.",
      "poi_id": "p20"
    }
  ]
}
